begin;
create function identity_adoption_v8.reject(code text)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('status','rejected','code',code,'effects',false)$$;
create function identity_adoption_v8.apply(actor uuid,sid uuid,tid uuid,op uuid,req jsonb)returns jsonb language plpgsql security invoker set search_path='' as $$declare r app.tournament_roster_entries%rowtype;d jsonb;e jsonb;a jsonb;x jsonb;q jsonb;p jsonb;matches integer;newname text;cov text;rid uuid;begin
if not identity_trial_v4.exact(req,array['kind','rosterEntryId','sourceDigest','inventoryDigest','expectedRevision','draft','coverage','duplicateReviewed','reason'])or req->>'kind'is distinct from'legacy-adoption-request-v8'or req->'duplicateReviewed'is distinct from'true'::jsonb or not identity_trial_v4.txt(req->'reason',500,true)or coalesce(req->>'sourceDigest','')!~'^[a-f0-9]{64}$'or coalesce(req->>'inventoryDigest','')!~'^[a-f0-9]{64}$'or jsonb_typeof(req->'expectedRevision')is distinct from'number'or req->>'expectedRevision'!~'^[0-9]+$'or(req->>'expectedRevision')::numeric>9007199254740991 or coalesce(req->>'rosterEntryId','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then return identity_adoption_v8.reject('invalid_request');end if;
if req->>'rosterEntryId'is distinct from lower(req->>'rosterEntryId')then return identity_adoption_v8.reject('invalid_request');end if;rid:=(req->>'rosterEntryId')::uuid;d:=req->'draft';e:=d->'entry';a:=d->'address';x:=d->'distinction';cov:=req->>'coverage';newname:=identity_trial_v4.display_name(e,x);if d->>'idempotencyKey'is distinct from lower(d->>'idempotencyKey')then return identity_adoption_v8.reject('invalid_request');end if;
if not identity_trial_v4.exact(d,array['kind','idempotencyKey','entry','address','distinction','privateDeskNote'])or d->>'kind'is distinct from'manual-roster-identity-request-v3'or coalesce(d->>'idempotencyKey','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'or d->>'privateDeskNote'is distinct from''or not identity_trial_v4.valid_entry(e)or e->>'scorecardType'<>'paper'or not identity_trial_v4.exact(a,array['street','postalCode','country'])or not(identity_trial_v4.txt(a->'street',300)and identity_trial_v4.txt(a->'postalCode',40)and identity_trial_v4.txt(a->'country',80))or newname is null or cov not in('complete','incomplete_reviewed')or(cov='complete')is distinct from(identity_trial_v4.match_key(e,a)is not null)then return identity_adoption_v8.reject('invalid_request');end if;
select*into r from app.tournament_roster_entries where id=rid and tournament_id=tid;if not found then return identity_adoption_v8.reject('legacy_target_unavailable');end if;
if exists(select 1 from identity_legacy_v1.adoptions where tournament_id=tid and roster_id=rid)or exists(select 1 from identity_trial_v4.facts where tournament_id=tid and roster_id=rid)then return identity_adoption_v8.reject('already_adopted');end if;
if exists(select 1 from app.roster_account_links where tournament_id=tid and roster_entry_id=rid)or exists(select 1 from app.event_participants where tournament_id=tid and roster_entry_id=rid and profile_id is not null)then return identity_adoption_v8.reject('account_identity_review_required');end if;
if coalesce((select event_type from app.roster_entry_lifecycle_events where tournament_id=tid and roster_entry_id=rid order by version desc limit 1),'active')='withdrawn'then return identity_adoption_v8.reject('withdrawn');end if;
if r.claimed_first_name is null or r.claimed_last_name is null then return identity_adoption_v8.reject('legal_name_review_required');end if;
if r.scorecard_type<>'paper'then return identity_adoption_v8.reject('digital_identity_review_required');end if;
if req->>'sourceDigest'is distinct from identity_legacy_v1.digest(tid,rid)or req->>'inventoryDigest'is distinct from identity_adoption_v8.inventory_digest(tid)or(req->>'expectedRevision')::numeric<>(select revision from identity_trial_v4.heads where tournament_id=tid)then return identity_adoption_v8.reject('stale_context');end if;
if e->>'firstName'<>r.claimed_first_name or e->>'lastName'<>r.claimed_last_name or e->>'email'<>coalesce(r.claimed_email,'')or e->>'accNumber'<>coalesce(r.claimed_acc_number,'')then return identity_adoption_v8.reject('invalid_request');end if;
select count(*)into matches from app.tournament_roster_entries other where other.tournament_id=tid and other.id<>rid and(other.claimed_first_name is null or other.claimed_last_name is null or identity_trial_v4.norm(other.claimed_first_name||' '||other.claimed_last_name)=identity_trial_v4.norm(r.claimed_first_name||' '||r.claimed_last_name));
matches:=matches+(select count(*)from identity_trial_v4.latest(tid)f where f.roster_id<>rid and not exists(select 1 from app.tournament_roster_entries lr where lr.id=f.roster_id and lr.tournament_id=tid)and identity_trial_v4.norm((f.entry->>'firstName')||' '||(f.entry->>'lastName'))=identity_trial_v4.norm(r.claimed_first_name||' '||r.claimed_last_name));
if matches>0 and(not exists(select 1 from jsonb_each_text(x)where trim(value)<>'')or exists(select 1 from identity_trial_v4.latest(tid)f where f.roster_id<>rid and identity_trial_v4.norm(f.display_name)=identity_trial_v4.norm(newname))or exists(select 1 from app.tournament_roster_entries other where other.tournament_id=tid and other.id<>rid and identity_trial_v4.norm(other.claimed_display_name)=identity_trial_v4.norm(newname)))then return identity_adoption_v8.reject('distinct_label_required');end if;
if coalesce(e->>'accNumber','')<>''then
perform pg_advisory_xact_lock(hashtextextended('identity-issued:'||(e->>'accNumber'),0));
if exists(select 1 from identity_trial_v4.issued where identity_legacy_v1.reference_key(number)=identity_legacy_v1.reference_key(e->>'accNumber'))or exists(select 1 from identity_trial_v4.issued_retired where identity_legacy_v1.reference_key(number)=identity_legacy_v1.reference_key(e->>'accNumber'))then return identity_adoption_v8.reject('issued_identity_review_required');end if;end if;
select count(*)into matches from identity_trial_v4.latest(tid)where match_key=identity_trial_v4.match_key(e,a);
q:=jsonb_build_object('action','create','expectedRevision',req->'expectedRevision','expectedVersion',0,'rosterEntryId',rid,'entry',e,'address',a,'distinction',x,'decision',case when cov='complete'and matches>0 then jsonb_build_object('action','distinct')else'null'::jsonb end,'reason',req->>'reason','issuedEvidence','');
p:=identity_adoption_v8.write_inner(actor,sid,tid,op,q,cov='incomplete_reviewed');
if p->>'status'<>'recorded'then return identity_adoption_v8.reject(case when p->>'status'='idempotency_conflict'then'idempotency_conflict'else'invalid_request'end);end if;
if p->'player'->>'rosterEntryId'<>rid::text then raise exception'legacy_id_changed';end if;
insert into identity_legacy_v1.adoptions(tournament_id,roster_id,subject_id,actor_id,operation_id,request,source_digest)values(tid,rid,(p->'player'->>'playerIdentityId')::uuid,actor,op,q,req->>'sourceDigest');
insert into identity_adoption_v8.reviews(tournament_id,roster_id,subject_id,coverage,actor_id,operation_id,request)values(tid,rid,(p->'player'->>'playerIdentityId')::uuid,cov,actor,op,req);
return jsonb_build_object('status','recorded','coverage',cov,'player',p->'player');end$$;
create function identity_adoption_v8.rebind(actor uuid,sid uuid,tid uuid,response jsonb)returns jsonb language plpgsql security invoker set search_path='' as $$begin
if response->>'status'='recorded'then
if not identity_adoption_v8.row_safe(tid,(response->'player'->>'rosterEntryId')::uuid)then return jsonb_set(jsonb_set(response,'{status}','"recorded_binding_review_required"'::jsonb),'{player,sessionId}',to_jsonb(sid));end if;
return jsonb_set(response,'{player,sessionId}',to_jsonb(sid));end if;return response;end$$;
create function identity_adoption_v8.write(actor uuid,sid uuid,tid uuid,op uuid,req jsonb)returns jsonb language plpgsql security invoker set search_path='' as $$declare prior identity_adoption_v8.operations%rowtype;outcome jsonb;begin
perform identity_adoption_v8.lock_scope(actor,sid,tid,true);if op is null then return identity_adoption_v8.reject('invalid_request');end if;
select*into prior from identity_adoption_v8.operations where tournament_id=tid and actor_id=actor and operation_id=op;
if found then return case when prior.request=req then identity_adoption_v8.rebind(actor,sid,tid,prior.response)else identity_adoption_v8.reject('idempotency_conflict')end;end if;
if exists(select 1 from identity_trial_v4.operations where tournament_id=tid and actor_id=actor and operation_id=op)then return identity_adoption_v8.reject('idempotency_conflict');end if;
outcome:=identity_adoption_v8.apply(actor,sid,tid,op,req);if outcome is null then raise exception'adoption_outcome_missing';end if;
insert into identity_adoption_v8.operations values(tid,actor,op,req,outcome);return outcome;end$$;
create function identity_adoption_v8.reconcile(actor uuid,sid uuid,tid uuid,op uuid,req jsonb)returns jsonb language plpgsql security invoker set search_path='' as $$declare prior identity_adoption_v8.operations%rowtype;begin
perform identity_adoption_v8.lock_scope(actor,sid,tid);select*into prior from identity_adoption_v8.operations where tournament_id=tid and actor_id=actor and operation_id=op;
if not found then return jsonb_build_object('status','absent');end if;
return case when prior.request=req then identity_adoption_v8.rebind(actor,sid,tid,prior.response)else identity_adoption_v8.reject('idempotency_conflict')end;end$$;
revoke all on all tables in schema identity_adoption_v8 from public,anon,authenticated,service_role;
revoke all on all functions in schema identity_adoption_v8 from public,anon,authenticated,service_role;
commit;
